const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(v)||0);
const uid=()=>crypto.randomUUID(),date=v=>new Date(v).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
let me,store,view='overview',mode='web',connection={web:{status:'disconnected'},official:{status:'disconnected'}},poll,register=false,selectedCustomer='',tab='store',timer;
async function api(p,method='GET',data,timeoutMs=15000){const r=await fetch('/api'+p,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(timeoutMs)});const type=r.headers.get('content-type')||'';if(!type.includes('application/json'))throw Error('Start the MarketLoop server to use accounts and WhatsApp. Opening the HTML file alone cannot run the backend.');const b=await r.json();if(!r.ok){if(r.status===401&&me){me=null;clearInterval(poll);$('#app').hidden=true;location.assign('/client-login')}throw Error(b.error||'Request failed')}return b}
function toast(msg){$('#toast').textContent=msg;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,7000)}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal()}
function close(){$('#modal').close()}
$('.modal-close').onclick=close;
function page(title,description,action=''){return `<div class="page-head"><div><h2>${title}</h2><p>${description}</p></div>${action}</div>`}
function pill(v){return `<span class="pill ${['Pending','Draft','New','Unpaid'].includes(v)?'amber':v==='Cancelled'?'red':''}">${esc(v)}</span>`}
function table(head,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${head.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-icon">▦</div>Nothing here yet. Add your first record to get started.</div>`}
const row=c=>`<tr>${c.map(v=>`<td>${v}</td>`).join('')}</tr>`;
function customer(id){return store.customers.find(c=>c.id===id)}
function orderTotal(o){return o.items.reduce((s,i)=>s+i.qty*i.price,0)+Number(o.deliveryFee||0)}
function input(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(name,label,items,value){return `<label>${label}<select name="${name}">${items.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`}
function formEnd(text='Save'){return `<div class="actions"><button type="button" class="btn secondary" data-close>Cancel</button><button class="btn">${text}</button></div></form>`}
function bindForm(fn){$('[data-close]',$('#modal'))?.addEventListener('click',close);$('#edit-form').onsubmit=async e=>{e.preventDefault();const b=$('button:not([type=button])',e.target);if(b)b.disabled=true;try{await fn(Object.fromEntries(new FormData(e.target)),e.target);close()}catch(err){toast(err.message);if(b)b.disabled=false}}}
async function persist(){await api('/store','PUT',store);store=await api('/store');render();toast('Saved to your store')}
$('#auth-toggle').onclick=()=>{register=!register;$('.register-only').hidden=!register;$('[name=name]').required=register;$('#auth-title').textContent=register?'Create your store.':'Welcome back.';$('#auth-sub').textContent=register?'Your store gets its own private workspace.':'Sign in to manage your supermarket.';$('#auth-submit').textContent=register?'Create account →':'Sign in →';$('#auth-toggle').textContent=register?'Already have an account? Sign in':'New here? Create your store account';$('#auth-error').textContent=''};
$('#login-form').onsubmit=async e=>{e.preventDefault();$('#auth-submit').disabled=true;try{await api(register?'/auth/register':'/auth/login','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();await boot()}catch(err){$('#auth-error').textContent=err.message}finally{$('#auth-submit').disabled=false}};
let signingOut=false;
async function signOut(){if(signingOut)return;signingOut=true;const buttons=[$('#logout'),$('#profile-logout'),$('#header-logout')].filter(Boolean);buttons.forEach(b=>b.disabled=true);try{await api('/auth/logout','POST',{});clearInterval(poll);location.assign('/logout')}catch(e){signingOut=false;buttons.forEach(b=>b.disabled=false);toast(e.message)}}
$('#logout').onclick=signOut;
$('#menu').onclick=()=>document.body.classList.toggle('nav-open');
