const menus=[['database','▦','Data Center'],['overview','◫','Overview'],['products','▦','Products & stock'],['customers','♙','Customers'],['ordering','◉','Ordering assistant'],['fulfilment','▤','Staff queue'],['orders','▤','Orders'],['whatsapp',whatsappMenuIcon,'WhatsApp Chats'],['inbox','☏','Inbox'],['campaigns','↗','Daily PDFs & offers'],['payments','₹','Payments'],['delivery','▱','Delivery'],['automations','⚡','Automations'],['reports','▥','Reports'],['settings','⚙','Store settings']];
async function boot(){if(location.protocol==='file:'){$('#auth').hidden=false;$('#auth-title').textContent='Start your store server.';$('#auth-sub').textContent='The page layout is available, but signing in needs the running application.';$('#login-form').hidden=true;$('#auth-toggle').hidden=true;$('#auth-error').className='note warning';$('#auth-error').innerHTML='<b>Open the MarketLoop folder and double-click Start-MarketLoop.cmd.</b><br>It installs missing dependencies, starts the backend and opens the dashboard.<br><br>Then use <a href="http://127.0.0.1:3080/client">http://127.0.0.1:3080/client</a> instead of opening this HTML file.';return}try{me=await api('/me');if(me.role==='client')store=await api('/store');$('#auth').hidden=true;$('#app').hidden=false;$('#role-label').textContent=me.role==='admin'?'Application administrator':'Owner workspace';$('.header-right .badge').textContent=me.role==='admin'?'Administrator':'Client workspace';$('#nav').innerHTML=(me.role==='admin'?[['admin','♙','Client access']]:menus).map(([id,icon,title])=>`<button data-view="${id}"><span>${icon}</span>${title}</button>`).join('');$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));if(me.role==='admin'){view='admin';$('#sidebar-store').textContent='Application management'}render();if(me.role==='client'){await refreshConnection();clearInterval(poll);poll=setInterval(async()=>{try{await refreshConnection()}catch{}},4000)}}catch(e){if(!me){if(e.message.includes('Sign in'))location.replace('/client-login');else{$('#auth').hidden=false;$('#login-form').hidden=true;$('#auth-toggle').hidden=true;$('#auth-error').textContent=e.message}}else toast(e.message)}}
function navigate(v){view=v==='connection'?'overview':v;document.body.classList.remove('nav-open');render()}
function render(){if(!me)return;if(view==='connection')view='overview';if(me.role==='client'){$('#sidebar-store').textContent=store.settings.name;$('#initials').textContent=store.settings.name.slice(0,1).toUpperCase()}$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent=menus.find(x=>x[0]===view)?.[2]||'Client access';const views={fulfilment:fulfilmentView,ordering:orderingView,database:dataCenter,overview,products,customers,orders,whatsapp:whatsappChatsPage,inbox,campaigns,payments,delivery,automations,reports,settings,admin};views[view]();}
function overview(){const active=store.orders.filter(o=>!['Delivered','Cancelled'].includes(o.status));const paid=store.orders.filter(o=>o.payment==='Paid');const low=store.products.filter(p=>p.stock<=p.lowStock);$('#view').innerHTML=page('Your store, at a glance.',new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),'<button class="btn" id="new-order">+ Create order</button>')+`<div class="hero-box"><div><h3>${connection.web.status==='connected'||connection.official.status==='connected'?'Your WhatsApp is connected.':'Connect your customers to your store.'}</h3><p>Link WhatsApp to receive messages. Your products and orders are ready to organise.</p></div><button class="btn" id="go-orders">View orders</button></div><div class="stats">${[['Recorded paid orders',money(paid.reduce((s,o)=>s+orderTotal(o),0)),'Includes manual payment records'],['Active orders',active.length,'Awaiting fulfilment'],['Customers',store.customers.length,'Your store customer list'],['Low-stock products',low.length,'At or below your alert threshold']].map(([l,v,h])=>`<div class="stat"><div class="stat-label">${l}<span>↗</span></div><div class="value">${v}</div><small>${h}</small></div>`).join('')}</div><div class="grid-two"><div class="panel"><div class="panel-head"><h3>Recent orders</h3><small>Latest 5</small></div>${orderTable(store.orders.slice(-5).reverse(),false)}</div><div class="panel"><h3>Your setup checklist</h3>${[['Add your products',store.products.length>0,'products'],['Save your first customer',store.customers.length>0,'customers'],['Set delivery areas',!!store.settings.areas,'settings']].map(([name,done,v])=>`<div class="card-row"><span class="row-icon">${done?'✓':'○'}</span><div><b>${name}</b><small>${done?'Ready':'Needs your attention'}</small></div><button class="btn small secondary" data-goto="${v}">Open</button></div>`).join('')}</div></div>`;$('#go-orders').onclick=()=>navigate('orders');$('#new-order').onclick=()=>editOrder();$$('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto))}
async function refreshConnection(){connection=await api('/whatsapp/status');const connected=connection.web.status==='connected'||connection.official.status==='connected';$('#sidebar-status').textContent=connected?'WhatsApp connected':'WhatsApp disconnected';$('.status-dot').style.background=connected?'#68a63c':'#b2b8a9';}
let metaInfo=null,metaCode=null;
window.addEventListener('message',e=>{if(!['https://www.facebook.com','https://web.facebook.com'].includes(e.origin))return;let d=e.data;try{if(typeof d==='string')d=JSON.parse(d)}catch{return}if(d?.type==='WA_EMBEDDED_SIGNUP'&&['FINISH','FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING'].includes(d.event)){metaInfo=d.data;finishMeta()}});
async function finishMeta(){if(!metaCode||!metaInfo?.phone_number_id||!metaInfo?.waba_id)return;const code=metaCode;metaCode=null;try{await api('/whatsapp/official/finish','POST',{code,phoneId:metaInfo.phone_number_id,waba:metaInfo.waba_id});metaInfo=null;await refreshConnection();toast('Official account authorized. Configure webhooks and verify number readiness before sending.')}catch(e){toast(e.message)}}
async function connectMeta(){try{const c=await api('/whatsapp/official/config');if(!window.FB){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://connect.facebook.net/en_US/sdk.js';script.onload=resolve;script.onerror=()=>reject(Error('Meta SDK could not load'));document.head.append(script)});window.FB.init({appId:c.appId,version:c.version,xfbml:false,cookie:true})}metaInfo=null;metaCode=null;window.FB.login(r=>{if(r.authResponse?.code){metaCode=r.authResponse.code;finishMeta()}else toast('Meta onboarding was cancelled or not completed')},{config_id:c.configId,response_type:'code',override_default_response_type:true,extras:{sessionInfoVersion:'3'}})}catch(e){$('#connection-error').textContent=e.message}}
function products(){const term=$('#product-search')?.value||'';$('#view').innerHTML=page('Products & stock.','Keep pack sizes, prices and available quantities up to date.','<button class="btn" id="add-product">+ Add product</button>')+`<div class="panel"><div class="toolbar"><input id="product-search" placeholder="Search products or brands" value="${esc(term)}"><button class="btn secondary" id="export-products">Export CSV</button></div><div id="products-table"></div></div>`;$('#add-product').onclick=()=>editProduct();$('#product-search').oninput=productRows;$('#export-products').onclick=()=>csv('products',store.products,['name','brand','unit','price','stock','lowStock']);productRows()}
function productRows(){const q=$('#product-search').value.toLowerCase();$('#products-table').innerHTML=table(['PRODUCT','PACK / UNIT','PRICE','STOCK','STATUS',''],store.products.filter(p=>(p.name+' '+p.brand).toLowerCase().includes(q)).map(p=>row([`<b>${esc(p.name)}</b><small>${esc(p.brand)}</small>`,esc(p.unit),money(p.price),esc(p.stock),pill(p.stock===0?'Out of stock':p.stock<=p.lowStock?'Low stock':'Available'),`<button class="btn secondary small" data-edit="${p.id}">Edit</button>`])));$$('[data-edit]').forEach(b=>b.onclick=()=>editProduct(b.dataset.edit))}
function editProduct(id){const p=store.products.find(x=>x.id===id)||{};modal(`<h2>${id?'Edit':'Add'} product</h2><form id="edit-form">${input('name','Product name',p.name,'text','required maxlength="120"')}<div class="two-fields">${input('brand','Brand',p.brand)}${input('unit','Pack size / unit',p.unit||'1 kg','text','required')}</div><div class="two-fields">${input('price','Selling price ₹',p.price??0,'number','min="0" step="0.01" required')}${input('stock','Available quantity',p.stock??0,'number','min="0" step="0.001" required')}</div>${input('lowStock','Low-stock alert threshold',p.lowStock??5,'number','min="0" step="0.001" required')}${formEnd()}`);bindForm(async b=>{const next={...p,id:id||uid(),...b,price:Number(b.price),stock:Number(b.stock),lowStock:Number(b.lowStock)};store.products=id?store.products.map(x=>x.id===id?next:x):[...store.products,next];await persist()})}
function customers(){$('#view').innerHTML=page('Your customers.','Keep delivery details and messaging permissions together.','<button class="btn" id="add-customer">+ Add customer</button>')+`<div class="panel"><div class="toolbar"><input id="customer-search" placeholder="Search name or phone"><button class="btn secondary" id="export-customers">Export CSV</button></div><div id="customer-table"></div></div>`;$('#add-customer').onclick=()=>editCustomer();$('#customer-search').oninput=customerRows;$('#export-customers').onclick=()=>csv('customers',store.customers,['name','phone','address','postcode','marketingConsent','serviceConsent']);customerRows()}
function customerRows(){const q=$('#customer-search').value.toLowerCase();$('#customer-table').innerHTML=table(['CUSTOMER','PHONE','DELIVERY ADDRESS','PROMOTIONS',''],store.customers.filter(c=>(c.name+c.phone).toLowerCase().includes(q)).map(c=>row([`<b>${esc(c.name)}</b>`,esc(c.phone),esc(c.address||'Not added'),pill(c.marketingConsent?'Subscribed':'Not subscribed'),`<button class="btn small secondary" data-customer="${c.id}">Edit</button>`])));$$('[data-customer]').forEach(b=>b.onclick=()=>editCustomer(b.dataset.customer))}
function editCustomer(id){const c=customer(id)||{};modal(`<h2>${id?'Edit':'Add'} customer</h2><form id="edit-form">${input('name','Full name',c.name,'text','required maxlength="100"')}${input('phone','WhatsApp number with country code',c.phone,'tel','required pattern="[+0-9 ()-]{8,20}"')}<label>Delivery address<textarea name="address" maxlength="500">${esc(c.address)}</textarea></label><div class="two-fields">${input('postcode','Postcode',c.postcode)}${input('consentSource','Consent source / reference',c.consentSource)}</div><label class="check"><input name="serviceConsent" type="checkbox" ${c.serviceConsent?'checked':''}>Customer agreed to order/service WhatsApp messages</label><label class="check"><input name="marketingConsent" type="checkbox" ${c.marketingConsent?'checked':''}>Customer explicitly subscribed to promotional updates</label><p class="hint">Record actual permission. An order alone is not permission for daily promotions. Uncheck promotions immediately when a customer opts out.</p>${formEnd()}`);bindForm(async b=>{const next={id:id||uid(),...b,serviceConsent:b.serviceConsent==='on',marketingConsent:b.marketingConsent==='on',consentAt:b.marketingConsent==='on'?(c.consentAt||new Date().toISOString()):null};store.customers=id?store.customers.map(x=>x.id===id?next:x):[...store.customers,next];await persist()})}
function orderTable(list,actions=true){return table(['ORDER','CUSTOMER','TOTAL','STATUS',...(actions?['']:[])],list.map(o=>row([`<b>${esc(o.number)}</b><small>${date(o.at)}</small>`,esc(customer(o.customerId)?.name||'Customer removed'),money(orderTotal(o)),pill(o.status),...(actions?[`<button class="btn secondary small" data-order="${o.id}">View order</button> <button class="btn small" data-order-sheet="${o.id}">Send to Sheets</button>`]:[])])))}
function orders(){const cfg=JSON.parse(localStorage.getItem('marketloop-google-orders')||'{}');$('#view').innerHTML=page('Every order, organised.','Confirm availability, pack carefully and keep delivery moving.','<button class="btn" id="add-order">+ Create order</button>')+`<div class="panel"><h3>Google Sheets order export</h3><p>Read, edit and append orders from your Google Sheet. Connect Google in Products & stock first.</p><form id="orders-sheet-form"><div class="two-fields"><label>Google spreadsheet<select id="orders-google-sheet-select" name="spreadsheet" required><option value="">Loading your Google Sheets…</option></select></label>${input('tab','Sheet tab name',cfg.tab||'Orders','text','required maxlength="100"')}</div><div class="actions"><button type="button" class="btn secondary" id="refresh-orders-google-sheets">Refresh spreadsheet list</button><button class="btn secondary">Save sheet destination</button></div></form><p class="hint">Expected columns: Name, Customer Address, Order Details with Quantity, Order Completion Status.</p><div class="actions"><button type="button" class="btn" id="load-google-orders">Load rows from Google Sheets</button><button type="button" class="btn secondary" id="toggle-orders-sheet-lock">🔒 Lock sheet editing</button></div><p id="orders-sheet-lock-status" class="hint">Checking sheet lock…</p><div id="google-orders-table"><p>Select Load rows from Google Sheets to view or edit the selected tab.</p></div></div><div class="panel"><div class="toolbar"><select id="order-filter"><option>All orders</option>${['New','Accepted','Packed','Out for delivery','Delivered','Cancelled'].map(s=>`<option>${s}</option>`).join('')}</select><button class="btn secondary" id="export-orders">Export CSV</button></div><div id="orders-table"></div></div>`;loadGoogleSpreadsheetOptions('orders-google-sheet-select',cfg.spreadsheet||'1FU5YQj0L63gvuHCAEaaUfMMosW82bUWiF8bzY0mu4Ec');$('#refresh-orders-google-sheets').onclick=()=>loadGoogleSpreadsheetOptions('orders-google-sheet-select',$('#orders-google-sheet-select').value||cfg.spreadsheet);$('#orders-sheet-form').onsubmit=e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));localStorage.setItem('marketloop-google-orders',JSON.stringify(b));toast('Google Sheets destination saved in this browser')};$('#load-google-orders').onclick=readGoogleOrders;$('#toggle-orders-sheet-lock').onclick=async()=>{try{const state=await api('/sheets'),next=await api('/sheets/lock','POST',{locked:!state.locked});$('#toggle-orders-sheet-lock').textContent=next.locked?'🔒 Unlock sheet editing':'🔓 Lock sheet editing';$('#orders-sheet-lock-status').textContent=next.locked?'Sheet is locked. Unlock it to update rows.':'Sheet is unlocked. Save changes writes edited rows to Google Sheets.';await readGoogleOrders()}catch(error){toast(error.message)}};$('#add-order').onclick=()=>editOrder();$('#order-filter').onchange=orderRows;$('#export-orders').onclick=()=>csv('orders',store.orders.map(o=>({...o,customer:customer(o.customerId)?.name,total:orderTotal(o)})),['number','customer','at','status','payment','total']);orderRows()}
async function readGoogleOrders(){const host=$('#google-orders-table'),button=$('#load-google-orders');if(!host)return;const cfg=JSON.parse(localStorage.getItem('marketloop-google-orders')||'{}');const form=$('#orders-sheet-form');const spreadsheet=form?.elements.spreadsheet.value||cfg.spreadsheet;if(!spreadsheet){host.innerHTML='<div class="note warning">Choose a Google spreadsheet first.</div>';return}if(button)button.disabled=true;host.innerHTML='<p>Connecting to Google Sheets…</p>';try{const status=await api('/sheets','GET',undefined,8000),lockButton=$('#toggle-orders-sheet-lock'),lockStatus=$('#orders-sheet-lock-status');if(lockButton)lockButton.textContent=status.locked?'🔒 Unlock sheet editing':'🔓 Lock sheet editing';if(lockStatus)lockStatus.textContent=status.locked?'Sheet is locked. Unlock it to update rows.':'Sheet is unlocked. Save changes writes edited rows to Google Sheets.';const result=await api('/sheets/orders/read','POST',{spreadsheet,tab:form?.elements.tab.value||cfg.tab||'Orders'},12000);const gridRows=result.rows.map(item=>({rowNumber:item.rowNumber,values:item.values||result.headers.map(header=>item[header])}));host.innerHTML=`<p>${result.rows.length} rows loaded from ${esc(form?.elements.tab.value||cfg.tab||'Orders')}.</p>${sheetTable({kind:'table',headers:result.headers,rows:gridRows,locked:status.locked})}`;ensureSaveChangesButton('google-orders-table','save-order-sheet-changes','toggle-orders-sheet-lock')}catch(error){host.innerHTML=`<div class="note warning">${esc(error.name==='TimeoutError'?'Google Sheets took too long to respond. Try loading the sheet again.':error.message)}. Connect Google under Products & stock, then load again.</div>`}finally{if(button)button.disabled=false}}
function orderRows(){const status=$('#order-filter').value;$('#orders-table').innerHTML=orderTable(store.orders.filter(o=>status==='All orders'||o.status===status).slice().reverse());$$('[data-order]').forEach(b=>b.onclick=()=>showOrder(b.dataset.order));$$('[data-order-sheet]').forEach(b=>b.onclick=async()=>{const cfg=JSON.parse(localStorage.getItem('marketloop-google-orders')||'{}');if(!cfg.spreadsheet)return toast('Save your Google Sheets destination first');b.disabled=true;try{await api('/sheets/orders/sync','POST',{orderId:b.dataset.orderSheet,spreadsheet:cfg.spreadsheet,tab:cfg.tab||'Orders'});b.textContent='Sent';toast('Order appended to Google Sheets')}catch(e){b.disabled=false;toast(e.message)}})}
function editOrder(){if(!store.products.length||!store.customers.length)return toast('Add at least one product and customer first');modal(`<h2>Create order</h2><form id="edit-form"><label>Customer<select name="customerId">${store.customers.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}</select></label><div id="order-items"></div><button type="button" class="btn secondary small" id="add-line">+ Add item</button><div class="two-fields">${input('deliveryFee','Delivery charge ₹',store.settings.deliveryFee||0,'number','min="0" step="0.01" required')}${select('fulfilment','Fulfilment',['Delivery','Store pickup'],'Delivery')}</div>${input('slot','Delivery slot / instructions','','text','maxlength="250"')}<div class="total" id="order-total"></div><p class="hint">Creating an order reserves its stock. Cancellation restores it. Stock is checked again on the server.</p>${formEnd('Create order')}`);const add=()=>{const div=document.createElement('div');div.className='order-lines';div.innerHTML=`<select class="item-product">${store.products.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.unit)} · ${money(p.price)}</option>`).join('')}</select><input class="item-qty" type="number" min="0.001" step="0.001" value="1" required aria-label="Quantity"><button type="button" class="icon-btn remove-line" aria-label="Remove item">×</button>`;$('#order-items').append(div);$('.remove-line',div).onclick=()=>{div.remove();calc()};$('select',div).onchange=calc;$('input',div).oninput=calc;calc()};const calc=()=>{const total=$$('.order-lines').reduce((s,d)=>s+(store.products.find(p=>p.id===$('select',d).value)?.price||0)*Number($('input',d).value||0),0)+Number($('[name=deliveryFee]').value||0);$('#order-total').textContent=money(total)};$('#add-line').onclick=add;$('[name=deliveryFee]').oninput=calc;add();bindForm(async b=>{const items=$$('.order-lines').map(d=>{const p=store.products.find(x=>x.id===$('select',d).value);return {productId:p.id,name:p.name,unit:p.unit,price:p.price,qty:Number($('input',d).value)}});if(!items.length)throw Error('Add at least one item');const amounts=new Map();items.forEach(i=>amounts.set(i.productId,(amounts.get(i.productId)||0)+i.qty));for(const [id,qty] of amounts){const p=store.products.find(x=>x.id===id);if(qty>p.stock)throw Error('Not enough stock: '+p.name)};await api('/orders','POST',{customerId:b.customerId,deliveryFee:Number(b.deliveryFee),fulfilment:b.fulfilment,slot:b.slot,items:items.map(i=>({productId:i.productId,qty:i.qty}))});store=await api('/store');render();toast('Order created and stock reserved')})}
function showOrder(id){const o=store.orders.find(x=>x.id===id),c=customer(o.customerId);modal(`<h2>Order ${esc(o.number)}</h2><p>${date(o.at)} · ${esc(o.fulfilment)}</p><div class="note"><b>${esc(c?.name)}</b><br>${esc(c?.phone)}<br>${esc(c?.address)} ${esc(c?.postcode)}<br>${esc(o.slot)}</div>${table(['ITEM','QUANTITY','TOTAL'],o.items.map(i=>row([esc(i.name)+' · '+esc(i.unit),i.qty,money(i.qty*i.price)])))}<div class="total">${money(orderTotal(o))}</div><form id="edit-form">${select('status','Order status',['New','Accepted','Packed','Out for delivery','Delivered','Cancelled'],o.status)}<p class="hint">Changing status saves the order. Automatic WhatsApp updates are not enabled yet.</p>${formEnd('Update order')}`);bindForm(async b=>{await api('/orders/'+id,'PATCH',{status:b.status});store=await api('/store');render();toast('Order updated')})}
function inbox(){if(!selectedCustomer||!customer(selectedCustomer))selectedCustomer=store.customers[0]?.id||'';$('#view').innerHTML=page('Customer conversations.','Receive connected WhatsApp messages and send individual service replies.','<button class="btn secondary" id="refresh-inbox">Refresh messages</button>')+`<div class="note">Official free-text replies need a customer message within the last 24 hours. Promotions require consent and the appropriate approved template. No messages are sent automatically.</div><div class="panel chat-layout"><div class="chat-list">${store.customers.map(c=>`<button data-chat="${c.id}" class="${c.id===selectedCustomer?'active':''}"><b>${esc(c.name)}</b><small style="display:block">${esc(c.phone)}</small></button>`).join('')||'<p>Add a customer to start.</p>'}</div><div class="chat-content"><h3>${esc(customer(selectedCustomer)?.name||'Select a customer')}</h3><div class="messages" id="messages"></div><form id="send-form"><select name="mode" aria-label="WhatsApp connection"><option value="web">Linked-device connection</option><option value="official">Official WhatsApp API</option></select><div class="chat-compose"><textarea name="text" placeholder="Write a service reply…" required maxlength="4000" aria-label="Message"></textarea><button class="btn" ${!selectedCustomer?'disabled':''}>Send</button></div></form></div></div>`;$$('[data-chat]').forEach(b=>b.onclick=()=>{selectedCustomer=b.dataset.chat;inbox()});$('#refresh-inbox').onclick=async()=>{try{store=await api('/store');inbox()}catch(e){toast(e.message)}};const number=String(customer(selectedCustomer)?.phone||'').replace(/\D/g,'');const messages=store.messages.filter(m=>m.from.replace('@c.us','').replace(/\D/g,'')===number);$('#messages').innerHTML=messages.map(m=>`<div class="message ${m.direction==='out'?'out':''}">${esc(m.text)}<small>${date(m.at)} · ${esc(m.mode)}</small></div>`).join('')||'<div class="empty">Messages appear here once your connection receives them.</div>';$('#messages').scrollTop=$('#messages').scrollHeight;$('#send-form').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));await api('/messages/send','POST',{...data,customerId:selectedCustomer});store=await api('/store');inbox();toast('Message accepted by connection')}catch(err){toast(err.message);b.disabled=false}}}
function campaigns(){$('#view').innerHTML=page('Daily products & PDFs.','Prepare promotional content for customers who explicitly subscribe.','<button class="btn" id="add-campaign">+ Prepare update</button>')+`<div class="note warning">Draft preparation works. Scheduled sending is not enabled: connect an approved template and campaign worker before delivery. Saving a time here does not send messages.</div><div class="stats"><div class="stat"><div class="stat-label">Subscribed customers</div><div class="value">${store.customers.filter(c=>c.marketingConsent).length}</div><small>Audience checked again before delivery</small></div><div class="stat"><div class="stat-label">Prepared drafts</div><div class="value">${store.campaigns.length}</div><small>No campaigns have been dispatched</small></div></div><div class="panel">${table(['UPDATE','PLANNED TIME','AUDIENCE','STATUS',''],store.campaigns.map(c=>row([`<b>${esc(c.title)}</b><small>${esc(c.fileName||'Text update')}</small>`,c.planned?date(c.planned):'Not set','Subscribed customers',pill('Draft'),`<button class="btn secondary small" data-campaign="${c.id}">Preview</button>`])))}</div>`;$('#add-campaign').onclick=editCampaign;$$('[data-campaign]').forEach(b=>b.onclick=()=>{const c=store.campaigns.find(x=>x.id===b.dataset.campaign);modal(`<h2>${esc(c.title)}</h2><div class="preview-text">${esc(c.text)}</div>${c.fileId?`<p><a class="btn secondary" href="/api/files/${esc(c.fileId)}" target="_blank" rel="noopener">Open saved PDF ↗</a></p>`:''}<div class="note">Draft only · Nothing has been sent.</div>`)})}
function editCampaign(){modal(`<h2>Prepare a daily update</h2><form id="edit-form">${input('title','Update title','','text','required maxlength="120"')}<label>Message<textarea name="text" required maxlength="4000" placeholder="Today's fresh products and offers…"></textarea></label><label>Attach catalogue PDF (up to 8 MB)<input name="pdf" type="file" accept="application/pdf"></label>${input('planned','Planned date and time (draft only)','','datetime-local')}<p class="hint">The time uses this device's timezone. It is stored as a draft, not an active sending schedule.</p>${formEnd('Save draft')}`);bindForm(async(b,form)=>{let fileId=null,fileName=null;const f=$('[name=pdf]',form).files[0];if(f){if(f.size>8*1024*1024)throw Error('Maximum PDF size is 8 MB');const base64=await new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});const uploaded=await api('/files','POST',{base64,name:f.name});fileId=uploaded.id;fileName=uploaded.name}store.campaigns.push({id:uid(),title:b.title,text:b.text,planned:b.planned?new Date(b.planned).toISOString():null,fileId,fileName,status:'Draft',at:new Date().toISOString()});await persist()})}
function payments(){$('#view').innerHTML=page('Payments, clearly tracked.','Track payment references against orders without assuming that a screenshot proves payment.')+`<div class="note warning">Payment gateway integration is not configured. These are manual records; payment links, online verification and refunds are unavailable until a gateway webhook is connected.</div><div class="panel">${table(['ORDER','CUSTOMER','AMOUNT','PAYMENT STATE','REFERENCE',''],store.orders.map(o=>row([esc(o.number),esc(customer(o.customerId)?.name),money(orderTotal(o)),pill(o.payment||'Unpaid'),esc(o.paymentReference||'—'),`<button class="btn secondary small" data-payment="${o.id}">Record payment</button>`])))}</div>`;$$('[data-payment]').forEach(b=>b.onclick=()=>{const o=store.orders.find(x=>x.id===b.dataset.payment);modal(`<h2>Payment for ${esc(o.number)}</h2><p>Total: ${money(orderTotal(o))}</p><form id="edit-form">${select('payment','Manual payment state',['Unpaid','Paid','Refunded'],o.payment||'Unpaid')}${input('reference','Bank / cash receipt reference',o.paymentReference,'text','required maxlength="150"')}<label class="check"><input name="verified" type="checkbox" required>I checked the store bank / cash records</label><div class="note">This is recorded as a manual confirmation. It is not a gateway-verified payment.</div>${formEnd('Save manual record')}`);bindForm(async b=>{await api('/orders/'+o.id+'/payment','PATCH',b);store=await api('/store');render();toast('Manual payment recorded')})})}
function delivery(){$('#view').innerHTML=page('Packing to doorstep.','Assign the responsible person and keep fulfilment status visible.')+`<div class="panel">${table(['ORDER','CUSTOMER & ADDRESS','SLOT','ASSIGNEE','STATUS',''],store.orders.filter(o=>o.status!=='Cancelled').map(o=>row([esc(o.number),`<b>${esc(customer(o.customerId)?.name)}</b><small>${esc(customer(o.customerId)?.address||'Pickup')}</small>`,esc(o.slot||'Not set'),esc(o.assignee||'Unassigned'),pill(o.status),`<button class="btn secondary small" data-delivery="${o.id}">Manage</button>`])))}</div>`;$$('[data-delivery]').forEach(b=>b.onclick=()=>{const o=store.orders.find(x=>x.id===b.dataset.delivery);modal(`<h2>Delivery · ${esc(o.number)}</h2><form id="edit-form">${input('assignee','Responsible staff member',o.assignee,'text','maxlength="100"')}${input('slot','Slot / delivery instructions',o.slot,'text','maxlength="250"')}${select('status','Status',['New','Accepted','Packed','Out for delivery','Delivered','Cancelled'],o.status)}${formEnd()}`);bindForm(async b=>{await api('/orders/'+o.id,'PATCH',b);store=await api('/store');render();toast('Fulfilment updated')})})}
function automations(){$('#view').innerHTML=page('Your automation plan.','Configure the behaviour you want before enabling a live workflow.')+`<div class="panel"><h3>Workflow readiness</h3>${[['Welcome message','Greet a new customer and offer shopping options.'],['Daily catalogue','Send approved promotional updates to subscribed customers.'],['Order confirmation','Send customer-confirmed items, quantities and final total.'],['Payment confirmation','Trigger only after verified gateway payment events.'],['Delivery updates','Notify customers when staff changes the delivery status.'],['Stock alerts','Alert staff when a product hits its stock threshold.']].map(([t,d])=>`<div class="card-row"><span class="row-icon">⚡</span><div><b>${t}</b><small>${d}</small></div><span class="pill neutral" style="margin-left:auto">Not enabled</span></div>`).join('')}<div class="note">No workflow is active. This prevents accidental sending while the WhatsApp connection, template approvals and payment gateway are being configured.</div></div>`}
function reports(){const completed=store.orders.filter(o=>o.status==='Delivered'),cancelled=store.orders.filter(o=>o.status==='Cancelled'),paid=store.orders.filter(o=>o.payment==='Paid');$('#view').innerHTML=page('Understand your store.','Totals reflect records in this workspace, including manually recorded payments.','<button class="btn secondary" id="report-export">Export order report</button>')+`<div class="stats">${[['Total orders',store.orders.length],['Delivered',completed.length],['Cancelled',cancelled.length],['Recorded paid value',money(paid.reduce((s,o)=>s+orderTotal(o),0))]].map(([l,v])=>`<div class="stat"><div class="stat-label">${l}</div><div class="value">${v}</div></div>`).join('')}</div><div class="panel"><h3>Orders over the last 7 days</h3><div class="bar-chart">${Array.from({length:7},(_,i)=>{const d=new Date;d.setDate(d.getDate()-6+i);const count=store.orders.filter(o=>new Date(o.at).toDateString()===d.toDateString()).length;const max=Math.max(1,store.orders.length);return `<div class="bar-col"><div style="height:${Math.max(2,count/max*100)}px" title="${count} orders"></div>${d.toLocaleDateString('en-IN',{weekday:'short'})}<br>${count}</div>`}).join('')}</div></div><div class="note">These figures do not represent accounting profit or bank reconciliation.</div>`;$('#report-export').onclick=()=>csv('order-report',store.orders.map(o=>({...o,total:orderTotal(o),customer:customer(o.customerId)?.name})),['number','at','customer','total','status','payment','paymentSource','paymentReference'])}
function settings(){$('#view').innerHTML=page('Make this workspace yours.','Save the rules your team follows for each order.')+`<div class="panel setting-panel"><form id="settings-form"><h3>Store details</h3><div class="two-fields">${input('name','Store name',store.settings.name,'text','required maxlength="100"')}${input('phone','Store phone',store.settings.phone,'tel')}</div><label>Store address<textarea name="address">${esc(store.settings.address)}</textarea></label><h3 style="margin-top:28px">Delivery & ordering</h3>${input('areas','Delivery areas / postcodes',store.settings.areas)}<div class="two-fields">${input('minimum','Minimum order ₹',store.settings.minimum,'number','min="0" step="0.01"')}${input('deliveryFee','Default delivery charge ₹',store.settings.deliveryFee,'number','min="0" step="0.01"')}</div>${input('freeAbove','Free delivery above ₹ (0 = disabled)',store.settings.freeAbove,'number','min="0" step="0.01"')}<div class="two-fields">${input('open','Opening time',store.settings.open,'time')}${input('close','Closing time',store.settings.close,'time')}</div>${input('cutoff','Same-day cutoff',store.settings.cutoff,'time')}${input('slots','Available delivery slots',store.settings.slots)}<h3 style="margin-top:28px">Payments & staff</h3>${input('paymentMethods','Accepted payment methods',store.settings.paymentMethods)}${input('upi','Store UPI ID (display details only)',store.settings.upi)}${input('staff','Order handling / packing staff',store.settings.staff)}${input('support','Customer support number',store.settings.support)}<div class="note">Prices and availability are checked when creating an order. Staff must confirm delivery area, time, substitutions and final bill before requesting payment.</div><button class="btn">Save store settings</button></form></div>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));for(const key of ['minimum','deliveryFee','freeAbove'])b[key]=Number(b[key]||0);const old=store.settings;store.settings={...old,...b};try{await persist()}catch(err){store.settings=old;toast(err.message)}}}
async function admin(){$('#view').innerHTML=page('Client access management.','Only the application administrator can enable or disable supermarket accounts.')+'<div class="panel" id="admin-list">Loading clients…</div>';try{const clients=await api('/admin/clients');$('#admin-list').innerHTML=table(['STORE','OWNER EMAIL','REGISTERED','APPLICATION ACCESS',''],clients.map(c=>row([`<b>${esc(c.name)}</b>`,esc(c.email),date(c.created),pill(c.enabled?'Enabled':'Disabled'),`<button class="btn small ${c.enabled?'danger':'secondary'}" data-access="${c.id}" data-enabled="${!c.enabled}">${c.enabled?'Disable access':'Enable access'}</button>`])));$$('[data-access]').forEach(b=>b.onclick=async()=>{if(!confirm(`${b.dataset.enabled==='true'?'Enable':'Disable'} this client's application access?`))return;try{await api('/admin/access','POST',{id:b.dataset.access,enabled:b.dataset.enabled==='true'});admin();toast('Client access updated')}catch(e){toast(e.message)}})}catch(e){toast(e.message)}}
function csv(name,data,fields){const safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const content=[fields.map(safe).join(','),...data.map(r=>fields.map(k=>safe(r[k])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='marketloop-'+name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
if(typeof document.addEventListener==='function'&&document.readyState!=='complete')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
